// Licenses of Leveret and of the open source packages it ships, generated by
// scripts/licenses.ps1 into third-party.json. Loaded on demand (about 500 KB).

export interface ThirdPartyPackage {
  ecosystem: 'rust' | 'npm'
  name: string
  version: string
  /** SPDX expression, e.g. "MIT OR Apache-2.0". */
  license: string
  repository: string
  /** Indexes into `texts`. */
  texts: number[]
}

export interface LicenseData {
  /** Leveret's own license (LICENSE). */
  self: string
  packages: ThirdPartyPackage[]
  texts: string[]
}

let cached: Promise<LicenseData> | null = null

export function loadLicenses(): Promise<LicenseData> {
  cached ??= import('./third-party.json?raw').then((m) => JSON.parse(m.default) as LicenseData)
  return cached
}
